# -*- coding: utf-8 -*-
"""
Translations for STm10001_03 (109 items)
Scene: Act Three - The Bathhouse and the Slave
"""

TRANS_03 = {
    'STm10001_03.4': 'Hồi 3',
    'STm10001_03.5': 'Nhà Tắm và Nô Lệ',
    'STm10001_03.6': 'Tại nhà tắm công cộng, bạn nghe kể rằng Olympia đã giải phóng toàn bộ nô lệ trong thành phố. Cải trang thành một nô lệ, Elis thăm dò được một lối tẩu thoát qua đường cống ngầm. Trước khi bạn kịp tìm cách trốn thoát, Alina bất ngờ cất lời hỏi bạn về thuật hồi sinh.',
    'STm10001_03.42': 'Chúng ta tới nơi rồi, thưa ==SEX12== Tu Giả. Chào mừng ngài đến với Nhà Tắm Olympia, được đặt tên nhằm tôn vinh Chấp Chính Quan.',
    'STm10001_03.57': 'Đây là nhân viên phục vụ của chúng tôi, Lulu. Cô ấy sẽ đáp ứng mọi nhu cầu của ngài.',
    'STm10001_03.63': 'Nhân Viên Nhà Tắm',
    'STm10001_03.74': 'Rất hân hạnh được đón tiếp hai vị. Nguyện xin Thần Ma Pháp luôn che chở cho cả hai.',
    'STm10001_03.80': 'Hôm nay nắng ở Filanis gay gắt lắm. Mời hai vị dùng thử món trà mật ong ướp lạnh đặc sản của quán chúng tôi. Nó sẽ giúp hai vị giải nhiệt nhanh chóng đấy ạ.',
    'STm10001_03.83': 'Và đây là khăn vải lanh ướp hương hoa cúc để hai vị lau tay.',
    'STm10001_03.100': 'Cô ấy còn chưa dứt lời, những cánh tay bóng ma đen tuyền đã lập tức hiện hình xung quanh chúng tôi.==W== Chúng nâng những chiếc cốc đất nung và khăn lau, dâng lên với sự chuẩn xác đến rợn người.',
    'STm10001_03.112': 'Đây là... ma pháp ư?',
    'STm10001_03.118': 'Hì hì, mong là cảnh tượng vừa rồi không làm hai vị giật mình. Tạo hình ma lực thành các chi thể là sở trường của em đấy ạ. Nhờ vậy mà một mình em có thể gánh vác công việc của cả một dàn người hầu.',
    'STm10001_03.123': 'Ái chà, xin thứ lỗi cho em. Mải tíu tít quá nên em quên mất chưa hỏi quý danh của hai vị.',
    'STm10001_03.129': 'Đây là chủ nhân của tôi, Tu Giả ==PLAYER_NAME==. Còn tôi là nô lệ hầu cận của ==SEX3==, Elis.',
    'STm10001_03.133': 'Chủ nhân...?==W== Nô lệ...?==W== Đội trưởng Alina, khoan đã! Sao lại có nô lệ ở đây thế này?',
    'STm10001_03.146': 'Ở đây cấm nô lệ sao? Ngay cả ở Emor, chủ nhân đi đâu thì nô lệ cũng phải theo đó phục dịch mà.',
    'STm10001_03.148': 'Lulu, họ không phải người ở Filanis. Trường hợp này hơi đặc biệt. Em đi chuẩn bị bồn tắm đi, ở đây cứ để chị lo.',
    'STm10001_03.151': 'V-Vâng ạ...',
    'STm10001_03.160': '<size=35>Trông đạo mạo đàng hoàng thế kia mà vẫn còn nuôi nô lệ. Đúng là thứ ký sinh trùng ghê tởm.',
    'STm10001_03.163': 'Này! Cô vừa nói cái gì đấy? Ăn nói cho cẩn thận trước mặt Chủ nhân của tôi đấy nhé!',
    'STm10001_03.169': 'Tôi thay mặt Lulu tạ lỗi với ngài. Vì quá khứ của bản thân, con bé không thể nào chịu đựng nổi những kẻ sở hữu nô lệ.',
    'STm10001_03.171': 'Thứ lỗi cho tôi hỏi nhé? Mọi gia đình ở Nova đều nuôi nô lệ mà. Đừng bảo với tôi là ở Filanis chẳng có lấy một mống nào đấy nhé?',
    'STm10001_03.173': 'Trước đây thì có. Nhưng giờ thì không còn nữa rồi.',
    'STm10001_03.178': 'Nhiều năm trước, người đứng đầu của chúng tôi, Chấp Chính Quan Olympia, đã trả tự do cho tất cả nô lệ trong thành phố==RT==và ban cho họ quyền công dân đầy đủ.',
    'STm10001_03.181': 'Kể từ đó, chúng tôi chỉ gắn kết với nhau bằng thiện chí và tình đồng chí hữu nghị.==RT==Chính nhờ vậy mà Filanis mới hưng thịnh trở thành Thành Phố Hoàn Hảo như ngày hôm nay.',
    'STm10001_03.183': 'G-Giải phóng toàn bộ bọn họ sao? Thế thì ai làm những công việc nặng nhọc tay chân?',
    'STm10001_03.184': 'Chấp Chính Quan Olympia đã chế tạo ra những con rối ma pháp. Chúng đảm nhiệm toàn bộ công việc nặng nhọc mà trước đây nô lệ từng phải làm.',
    'STm10001_03.186': 'Những con rối ư? Khoan đã, chẳng lẽ những thứ trong khu rừng lúc nãy...',
    'STm10001_03.208': 'Đúng vậy, đó chính là những con rối bị bỏ hoang của Filanis.',
    'STm10001_03.210': 'Chúng được đẽo gọt từ gỗ. Nếu không có ma lực truyền vào, chúng chẳng khác gì những con rối bình thường cả.',
    'STm10001_03.211': 'Người dân thường để lại những con rối đã hỏng trong rừng để chúng tự phân hủy về với tự nhiên. Tôi vẫn đang điều tra xem tại sao đám rối lúc nãy lại tự động cử động và tấn công chúng ta.',
    'STm10001_03.213': 'Thời gian không còn nhiều nữa. Xin ngài hãy tắm rửa nhanh lên. Giờ diện kiến Chấp Chính Quan Olympia sắp đến rồi.',
    'STm10001_03.215': 'Nếu ngài còn thắc mắc gì về Filanis, sau buổi diện kiến chúng ta có thể thong thả đàm đạo tiếp.',
    'STm10001_03.217': 'Alina, cảm ơn cô vì đã sắp xếp chu đáo mọi chuyện thế này. Có cách nào để tôi đền đáp cô không?',
    'STm10001_03.223': '(Với cô nàng Dạ Hành Giả kia cũng thế. Bỏ cái vẻ lịch thiệp nhã nhặn ấy đi, diễn thế lộ liễu lắm. Nhưng nếu cô ta phục vụ chu đáo, hãy ban thưởng cho cô ta thật hậu hĩnh.)',
    'STm10001_03.227': 'Elis bảo mình phải tỏ ra có quyền uy. Hy vọng vừa rồi nghe không bị gượng gạo quá.',
    'STm10001_03.229': 'Đó là bổn phận của tôi, thưa ==SEX12== Tu Giả.==W== Nhưng tôi quả thực có một thỉnh cầu. Nếu sau buổi diện kiến ngài còn chút thời gian rảnh, tôi muốn xin ngài chỉ giáo về một vấn đề ma pháp.',
    'STm10001_03.231': 'Được chứ.',
    'STm10001_03.271': 'Phù...==W== Đúng là thiên đường. Cuối cùng mình cũng cảm thấy như được sống lại.',
    'STm10001_03.275': 'Làn nước nóng khiến da thịt mình khoan khoái râm ran. Từng thớ cơ đang nhức mỏi đều được thả lỏng hoàn toàn.',
    'STm10001_03.279': 'Rốt cuộc đây là đâu?==W== Tại sao Elis và Alina trông lại quen thuộc đến thế? Mình phải nói gì với Chấp Chính Quan đây? Alina muốn xin lời khuyên về ma pháp, nhưng mình thì mù tịt ma thuật. Phải làm cách nào mới trở về được đây...',
    'STm10001_03.294': 'Những câu hỏi này...==W== lúc này mình chẳng muốn nghĩ ngợi gì thêm nữa. Mình chỉ muốn cứ ngâm mình lững lờ trôi thế này cho đến khi tan biến mà thôi.',
    'STm10001_03.296': 'Được rồi, không phải là mình không quan tâm đâu.==W== Chỉ là mình thực sự cần được nghỉ ngơi một chút lúc này.',
    'STm10001_03.301': 'Ồ, có thứ gì đó đang kỳ lưng cho mình. Cảm giác sảng khoái ghê gớm. Bồn tắm này có yểm sẵn ma pháp xoa bóp sao? Người Filanis đúng là biết hưởng thụ thật.',
    'STm10001_03.302': 'Khoan đã. Một nhà tắm mộc mạc thôn dã thế này làm sao có vòi phun xoa bóp được chứ?!',
    'STm10001_03.317': 'Hửm, hừm-hừm-hừm<size=52> ♪',
    'STm10001_03.319': 'E-Elis?! Cô đang làm cái trò gì thế hả?',
    'STm10001_03.322': 'Em đang kỳ lưng cho Chủ nhân mà.',
    'STm10001_03.323': 'Khoan đã! Cô chui vào đây từ lúc nào thế? Chẳng phải chúng ta được bố trí hai bồn tắm riêng biệt sao?',
    'STm10001_03.326': 'Ôi dào, Chủ nhân đừng có ngượng ngùng thế chứ. Làn da trắng trẻo và xương quai xanh quyến rũ thế kia cơ mà. Hãy tự tin lên!',
    'STm10001_03.327': 'Ôi dào, Chủ nhân đừng có ngượng ngùng thế chứ. Em đã quấn khăn tắm kín mít rồi, người sẽ không thấy điều gì bất nhã đâu. Còn vóc dáng hoàn hảo của người thì việc gì phải giấu giếm.',
    'STm10001_03.332': 'Dù sao thì chúng ta đều là con gái với nhau cả mà. Tắm chung một bồn thì có mất mát gì đâu chứ?',
    'STm10001_03.333': 'Dù sao thì anh cũng là đàn ông cơ mà. Mạnh mẽ lên xem nào!',
    'STm10001_03.336': 'Hơn nữa, em là nô lệ của người mà. Nô lệ tắm rửa kỳ lưng cho Chủ nhân chẳng phải là chuyện đương nhiên sao?',
    'STm10001_03.337': 'Đ-Đương nhiên cái nỗi gì? Chúng ta chỉ giả vờ làm chủ tớ để qua mắt người ngoài thôi. Tôi còn chẳng ưa nổi chế độ nô lệ, nói gì đến chuyện cần một người hầu.',
    'STm10001_03.338': 'Ồ? Chủ nhân ghét chế độ nô lệ chẳng khác nào dân bản xứ ở đây nhỉ. Sao lại thế?',
    'STm10001_03.339': 'Cớ sao một người lại có thể sở hữu một con người khác chứ? Cảm giác đó sai trái vô cùng. Tôi chẳng cần lý do nào to tát hơn thế cả.',
    'STm10001_03.340': 'Còn cô thì sao? Nếu cần một vỏ bọc, cô hoàn toàn có thể nhận làm bạn bè hay bạn đồng hành mà. Sao cứ nhất quyết phải làm nô lệ chứ?',
    'STm10001_03.343': 'Bởi vì làm thế rất thực tế. Anh bảo sở hữu người khác là sai trái. Nhưng lỡ như trong mắt người Nova, nô lệ ngay từ đầu vốn dĩ chẳng được coi là con người thì sao?',
    'STm10001_03.345': 'Không phải là người ư...',
    'STm10001_03.346': 'Hừm. Ở các khu chợ tại Emor, một con ngựa còn có giá đắt hơn nhiều so với một nô lệ. Đối với phần lớn người Nova, nô lệ chẳng qua chỉ là một món đồ vật không hơn không kém.',
    'STm10001_03.347': 'Và làm một món đồ vật thì lại có cái lợi của nó.',
    'STm10001_03.348': 'Lợi ích ở chỗ nào cơ chứ?',
    'STm10001_03.351': 'Chà, chẳng ai lại rỗi hơi đi soi mói một món đồ vật cả.==W== Và với em, đó chính là lợi thế lớn nhất.',
    'STm10001_03.352': 'Nếu em nhận là bạn đồng hành của anh, em sẽ phải bịa ra một lai lịch hoàn hảo không tì vết. Một vỏ bọc chắc chắn sẽ sụp đổ trước sự điều tra, nhất là khi em là một Thánh Nữ Sa Ngã đã trốn chui trốn nhủi trong tháp suốt ba năm.',
    'STm10001_03.353': 'Nhưng nếu là nô lệ? Em chỉ cần anh gật đầu một cái là xong. Mọi ánh mắt soi mói nghi ngờ sẽ đổ dồn hết lên người anh, bởi vì em chỉ đơn thuần là một món tài sản thuộc về anh mà thôi.',
    'STm10001_03.354': 'Này nhé. Cô tính toán đâu ra đấy thật đấy. Tôi chẳng biết cô là kẻ mưu mô xảo quyệt hay chỉ là kẻ liều mạng nữa.',
    'STm10001_03.355': 'Lỡ như tôi từ chối không chịu phối hợp thì sao? Hoặc lỡ tôi là kẻ nguy hiểm thì tính thế nào?',
    'STm10001_03.356': 'Lúc em tìm thấy thì anh chỉ là một cái xác không hồn, em việc gì phải sợ chứ.==W== Lúc anh tỉnh lại đúng là có làm em giật bắn mình thật, nhưng em đã quan sát anh rất kỹ trước khi quyết định tiếp tục diễn màn kịch này.',
    'STm10001_03.357': 'Anh hiền lành, nhân hậu, thông minh, lại còn hoàn toàn vô hại nữa.==W== Đúng là người tuyệt vời nhất mà em từng gặp luôn đó~',
    'STm10001_03.360': 'Haizz. Sao nghe lời khen đó chẳng khác nào một lời xúc phạm thế nhỉ?!',
    'STm10001_03.361': 'Thế nên đóng vai nô lệ của anh chẳng có chút rủi ro nào cả.==W== Em thậm chí còn dám cá là anh sẽ không bao giờ coi em như một món đồ vật đâu. Và em đã đúng.',
    'STm10001_03.362': 'Nhân tiện thì đây là lần đầu tiên em đóng vai nô lệ đấy nhé. Em diễn xuất sắc không tì vết đúng không nào? Lời khen ngợi của em đâu rồi?',
    'STm10001_03.365': 'Rồi rồi. Giỏi lắm.',
    'STm10001_03.366': 'Ít ra anh cũng phải giả vờ nói cho có tâm chút chứ!',
    'STm10001_03.368': 'Elis, cô lẻn vào bồn tắm của tôi không phải chỉ để buôn chuyện với làm nũng đấy chứ?',
    'STm10001_03.369': 'Haha, tại em nhập tâm vào vai diễn quá thôi. Suýt nữa thì quên mất chuyện chính.',
    'STm10001_03.370': 'Tắm xong chúng ta phải đi diện kiến Chấp Chính Quan rồi. Vở kịch này có thể qua mắt được một Dạ Hành Giả nơi thôn dã, nhưng tuyệt đối không thể lừa nổi Chấp Chính Quan đâu.',
    'STm10001_03.371': 'Thế chúng ta phải làm sao?',
    'STm10001_03.372': 'Chuồn thôi chứ còn sao nữa!',
    'STm10001_03.376': 'Chạy đằng trời. Những cánh tay ma pháp đen ngòm kia đang canh gác nghiêm ngặt mọi cửa ra vào và cửa sổ rồi. Nói là phục vụ, nhưng rõ ràng là giám sát.',
    'STm10001_03.378': 'Hí hí, lại thêm một đặc quyền của nô lệ này!==W== Lulu đúng là có theo dõi chúng ta thật,==W== nhưng ngay khi em bảo là em vào để "phục dịch Chủ nhân", mặt cô bé đỏ bừng lên rồi vội vã tránh đi vì quá ghê tởm.',
    'STm10001_03.381': 'Cô bé có thể căm thù những kẻ nuôi nô lệ, nhưng sâu thẳm trong lòng? Cô bé vẫn chỉ coi em là một món đồ chơi tình dục mà thôi.',
    'STm10001_03.385': 'Lúc này, chắc cô bé ngây thơ kia đang tưởng tượng ra đủ trò đồi bại mà chúng ta đang làm trong này rồi.==W== Có cho kẹo cô bé cũng chẳng dám nhìn trộm đâu.',
    'STm10001_03.388': 'Thủ đoạn của cô... thực dụng đến rợn người thật đấy.',
    'STm10001_03.389': 'Về điểm này cô ấy thực sự có nét giống Iris, nhưng Iris sẽ không bao giờ dám táo bạo đến mức này.==W== Em ấy chẳng bao giờ có thể dựng lên một lời nói dối tinh vi như vậy được.',
    'STm10001_03.390': 'Thực dụng thì có gì sai chứ? Huống hồ...==W== ngay cả khi còn là một Thánh Nữ, em cũng chỉ bị đối xử như…',
    'STm10001_03.392': 'Không có gì! Dù sao thì lúc lẻn sang đây em đã phát hiện ra một đường ống thoát nước thông ra bên ngoài rồi.',
    'STm10001_03.393': 'Anh cứ đi ra sảnh trước nói chuyện với Dạ Hành Giả đi. Chẳng phải cô ta có điều muốn thỉnh giáo anh sao?==W== Hãy tận dụng cơ hội đó để giữ chân cô ta.',
    'STm10001_03.395': 'Em sẽ chui qua cống ngầm rồi gây náo loạn ngoài đường phố. Một khi cô ta chạy đi kiểm tra, anh chỉ việc ung dung sải bước ra khỏi cửa chính thôi.',
    'STm10001_03.396': 'Kế hoạch hay đấy. Bên ngoài chỉ có mỗi Alina và Lulu. Nếu hai ta tách ra...==W== bọn họ chắc chắn sẽ ưu tiên đuổi theo vị Thánh Nữ Sa Ngã tình nghi trước.',
    'STm10001_03.397': 'Nhưng làm vậy chẳng phải cô sẽ biến thành mục tiêu công kích lớn nhất sao?',
    'STm10001_03.398': 'Đừng lo cho em, Chủ nhân. Ba năm trốn trong tòa tháp đó em ngày đêm miệt mài nghiên cứu ma pháp cơ mà.',
    'STm10001_03.403': 'Được rồi, mình đã mặc đồ xong xuôi. Giờ này chắc Elis đã chui vào đường cống ngầm rồi.',
    'STm10001_03.404': 'Giờ đến lượt Alina...==W== A, cô ấy ở đằng kia.',
    'STm10001_03.410': '<size=75>Hỡi Nữ Thần Trivia từ bi và toàn năng, xin hãy lắng nghe lời cầu nguyện của con.',
    'STm10001_03.412': '<size=75>Xin hãy đưa những người chị em đã ngã xuống của con về cõi trời cao,==RT==để họ được tung cánh bay lượn theo mười hai luồng gió.',
    'STm10001_03.413': 'Cô ấy đang... cầu nguyện trước Cự Tháp sao?',
    'STm10001_03.415': 'Ôi, thành thật xin lỗi ngài. Tôi mải cầu nguyện với Nữ Thần nên không để ý thấy ngài, thưa ==SEX12== Tu Giả.',
    'STm10001_03.416': 'Không sao đâu. Nhà tắm tuyệt vời lắm, bao nhiêu mệt mỏi đều tan biến hết cả.',
    'STm10001_03.417': 'Chẳng phải cô có chuyện muốn hỏi tôi sao? Chúng ta vẫn còn chút thời gian trước khi gặp Chấp Chính Quan. Cô cứ hỏi đi.',
    'STm10001_03.418': 'N-Ngay lúc này sao?==W== Nhưng mà...',
    'STm10001_03.419': 'Alina ngập ngừng, một điều hiếm thấy ở cô.==RT==Cô đưa mắt nhìn về phía Cự Tháp sừng sững hồi lâu,==RT==như thể đang tìm kiếm một lời chỉ dẫn từ định mệnh.',
    'STm10001_03.426': 'Cự Tháp vẫn chỉ đứng lặng thinh ở đó trong tĩnh lặng.==RT==Nó không đoái hoài đến những mối hoài nghi của người phàm,==RT==và hiển nhiên cũng chẳng đưa ra bất kỳ lời giải đáp nào.',
    'STm10001_03.428': 'Xin thứ lỗi vì đã để ngài phải đợi lâu, thưa ==SEX12== Tu Giả.',
    'STm10001_03.429': 'Câu hỏi của tôi có phần...==W== mạo phạm và vượt quá phận sự. Nếu có làm phật ý ngài, tôi xin được tạ lỗi trước.',
    'STm10001_03.430': 'Không sao đâu. Cô cứ nói đi.',
    'STm10001_03.432': 'Ngài có thể kể cho tôi nghe về <color=#3faeae>thuật hồi sinh</color> được không?',
    'STm10001_03.441': '<size=50>Ngài muốn trả giá bằng điều gì cũng được...==W== Tôi sẽ dâng cho ngài bất cứ thứ gì tôi có!',
}
